// Calculate metrics and format data for AI
const items = $input.all();
const formattedData = [];

for (const item of items) {
  const json = item.json;
  const impressions = parseFloat(json.Impressions) || 0;
  const clicks = parseFloat(json.Clicks) || 0;
  const conversions = parseFloat(json.Conversions) || 0;
  const spend = parseFloat(json.Spend) || 0;

  const ctr = impressions > 0 ? ((clicks / impressions) * 100).toFixed(2) : 0;
  const cvr = clicks > 0 ? ((conversions / clicks) * 100).toFixed(2) : 0;
  const cpa = conversions > 0 ? (spend / conversions).toFixed(2) : 0;

  formattedData.push({
    Date: json.Date,
    Campaign: json.Campaign,
    Impressions: impressions,
    Clicks: clicks,
    Conversions: conversions,
    Spend: spend,
    CTR: ctr + '%',
    CVR: cvr + '%',
    CPA: '$' + cpa
  });
}

// Create a markdown table string for the AI prompt
let tableString = '| Date | Campaign | Cost | CTR | CVR | CPA |\n|---|---|---|---|---|---|\n';
formattedData.forEach(row => {
  tableString += `| ${row.Date} | ${row.Campaign} | $${row.Spend} | ${row.CTR} | ${row.CVR} | ${row.CPA} |\n`;
});

return {
  json: {
    tableString,
    totalRecords: formattedData.length
  }
};

