/**
 * A simple Markdown to HTML converter in pure JS
 */
let md = $json.choices[0].message.content;

let html = md
  .replace(/### (.*)/g, '<h3>$1</h3>')
  .replace(/## (.*)/g, '<h2>$1</h2>')
  .replace(/# (.*)/g, '<h1>$1</h1>')
  .replace(/\*\*(.*)\*\*/g, '<b>$1</b>')
  .replace(/\*(.*)\*/g, '<i>$1</i>')
  .replace(/\|/g, '│') 
  .replace(/\n/g, '<br>');

const finalHtml = `<div style="font-family: sans-serif; line-height: 1.6; color: #333;">${html}<br><hr><p style="color: #888; font-size: 12px;">報告生成：Antigravity IDE</p></div>`;

return { html: finalHtml };
